<script type="text/javascript">
jQuery(document).ready(function($) {
"use strict";

/* ================= Scroll Link ================= */
$('.scroll-link a').on('click', function(e) {
  e.preventDefault();
  var target = $($(this).attr('href'));
  if (target.length) {
    $('html, body').animate({
      scrollTop: target.offset().top
    }, 800, 'linear');
  }
});

/* ================= Counter ================= */
if ($.fn.counterUp) {
  $('.emizentech-counter').counterUp({
    delay: 50,
    time: 3000
  });
}

/* ================= Outside Click ================= */
$(document).on('click', function(event) {
  if (!$(event.target).closest('.call-dropdown-link, .call-dropdown-wrap').length) {
    $('.call-dropdown-wrap').slideUp();
  }
});

/* ================= Hover Dropdown ================= */
$('.has-dropdown').hover(
  function() {
    $(this).addClass('dropdown-open');
  },
  function() {
    $(this).removeClass('dropdown-open');
  }
);

/* ================= Data Nav ================= */
$('[data-nav-link]').on('click', function(e) {
  e.preventDefault();
  var dataNavId = $(this).attr('data-nav-link');

  $('[data-nav-id="' + dataNavId + '"]')
    .siblings()
    .removeClass('active');

  $('[data-nav-id="' + dataNavId + '"]')
    .addClass('active');
});

/* ================= Popup ================= */
$('[data-popup-link]').on('click', function() {
  var dataPopupId = $(this).attr('data-popup-link');

  $('[data-popup-id="' + dataPopupId + '"]')
    .addClass('popup-open');

  $('html').addClass('popup-open-wrap');
});

$('.close-link').on('click', function() {
  $('[data-popup-id]').removeClass('popup-open');
  $('html').removeClass('popup-open-wrap');
});

/* ================= Dropdown Active ================= */
$('.main-dropdown li').on('click', function() {
  $(this).siblings().removeClass('active');
  $(this).addClass('active');
});

/* ================= Footer Collapse ================= */
$('.footer-collapse').on('click', function() {
  $(this).parents(".col-6").toggleClass('fmenu_open');
});

/* ================= Portfolio Popup ================= */
$('.portfolio-item').on('click', function() {
  $('html').addClass('popup-open-wrap');
});

/* ================= Mobile Menu ================= */
$('.emizentech-toggle').on('click', function() {
  $('.emizentech-navigation, .mobile-menu').toggleClass('open');
});

$('.close-icon').on('click', function() {
  $('.emizentech-navigation, .mobile-menu').removeClass('open');
});

/* ================= Call Dropdown ================= */
$('.call-dropdown-link').on('click', function() {
  $('.call-dropdown-wrap').slideToggle();
});

/* ================= Mobile Dropdown ================= */
$('.mobile-dropdown > a').on('click', function(e) {
  e.preventDefault();
  $('.mobile-dropdown').find('.mobile-dropdown-nav').stop().slideUp();
  $(this)
    .closest('.mobile-dropdown')
    .find('.mobile-dropdown-nav')
    .stop()
    .slideToggle();
});

$('.mobile-dropdown-icon').on('click', function() {
  $(this).parent().siblings().each(function() {
    $(this).find("ul.mobile-dropdown-sub").slideUp();
  });

  $(this)
    .parent()
    .find("ul.mobile-dropdown-sub")
    .slideToggle();
});




});
</script>

