<script>
  const items = Array.from(document.querySelectorAll('#whyList li'));
  function animateItem(index) {
    if (index >= items.length) return;
    const li = items[index];
    // Step 1: enable transition
    li.classList.add('animating');
    // Step 2: double rAF ensures browser paints the start state first
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        // Step 3: trigger the zoom-in
        li.classList.add('visible');
        // Step 4: wait for THIS item's transform to finish, then do the next
        li.addEventListener('transitionend', function handler(e) {
          if (e.propertyName !== 'transform') return;
          li.removeEventListener('transitionend', handler);
          animateItem(index + 1); // ← next item only after this one completes
        });
      });
    });
  }
  // Watch for the list entering the viewport
  let triggered = false;
  const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting && !triggered) {
        triggered = true;
        animateItem(0);
        observer.disconnect();
      }
    });
  }, { threshold: 0.15 });
  observer.observe(document.getElementById('whyList'));
</script>


<script>
    $(document).ready(function () {
  var owl = $('.my-carousel-3d').owlCarousel({
    loop: true,
    margin: 0,
    center: true,
    autoplay: false,
    smartSpeed: 500,
    nav: false,
    dots: false,
    responsive: {
      0:    { items: 1 },
      576:  { items: 2 },
      992:  { items: 3 },
      1200: { items: 5 }
    }
  });

  function assignActiveItemClasses() {
    $('.my-carousel-3d .owl-item').each(function () {
      var filtered = $(this).attr('class')
        .split(' ')
        .filter(function (c) {
          return !/^pos-\d+$/.test(c) &&
                 !/^prev-\d+$/.test(c) &&
                 !/^next-\d+$/.test(c) &&
                 c !== 'is-center';
        });
      $(this).attr('class', filtered.join(' '));
    });

    var $active = $('.my-carousel-3d .owl-item.active');
    var total   = $active.length;
    var mid     = Math.floor(total / 2);

    $active.each(function (i) {
      $(this).addClass('pos-' + (i + 1));
      var diff = i - mid;
      if (diff === 0) {
        $(this).addClass('is-center');
      } else if (diff < 0) {
        $(this).addClass('prev-' + Math.abs(diff));
      } else {
        $(this).addClass('next-' + diff);
      }
    });
  }

  // ✅ KEY FIX: bind BEFORE init so initialized event is caught
  owl.on('initialized.owl.carousel changed.owl.carousel', function () {
    setTimeout(assignActiveItemClasses, 0);
  });

  // ✅ SAFETY NET: also run after a short delay on page load
  setTimeout(assignActiveItemClasses, 100);

  $('#prev-btn').on('click', function () { owl.trigger('prev.owl.carousel'); });
  $('#next-btn').on('click', function () { owl.trigger('next.owl.carousel'); });
});
</script>
<script>
  function getDirection(e, el) {
    const { width, height, top, left } = el.getBoundingClientRect();
    const x = e.clientX - left - width  / 2;
    const y = e.clientY - top  - height / 2;
    // angle in degrees, 0 = right, goes clockwise
    const angle = Math.atan2(y, x) * (180 / Math.PI);
    // Shift so 0 = top
    const deg = ((angle + 225) % 360 + 360) % 360;
    return Math.floor(deg / 90); // 0=top 1=right 2=bottom 3=left — wait, let's recalc below
  }

  function directionFromAngle(e, el) {
    const r   = el.getBoundingClientRect();
    const x   = e.clientX - r.left;
    const y   = e.clientY - r.top;
    const w   = r.width;
    const h   = r.height;

    // Distances to each edge
    const top    = y;
    const bottom = h - y;
    const left   = x;
    const right  = w - x;

    const min = Math.min(top, bottom, left, right);
    if (min === top)    return 'top';
    if (min === bottom) return 'bottom';
    if (min === left)   return 'left';
    return 'right';
  }

  function getStartTransform(dir) {
    switch (dir) {
      case 'top':    return 'translateY(-101%)';
      case 'bottom': return 'translateY(101%)';
      case 'left':   return 'translateX(-101%)';
      case 'right':  return 'translateX(101%)';
    }
  }

  function getExitTransform(dir) {
    // Exit in the same direction it came from (reverses out)
    switch (dir) {
      case 'top':    return 'translateY(-101%)';
      case 'bottom': return 'translateY(101%)';
      case 'left':   return 'translateX(-101%)';
      case 'right':  return 'translateX(101%)';
    }
  }

  document.querySelectorAll('.srv-card').forEach(card => {
    const overlay = card.querySelector('.card-overlay');
    let lastDir = 'bottom';

    card.addEventListener('mouseenter', (e) => {
      const dir = directionFromAngle(e, card);
      lastDir = dir;

      // 1. Snap overlay to entry edge (no transition)
      overlay.style.transition = 'none';
      overlay.style.transform  = getStartTransform(dir);

      // 2. Force reflow so browser registers the start position
      overlay.getBoundingClientRect();

      // 3. Slide to centre with transition
      overlay.style.transition = 'transform 0.42s cubic-bezier(0.4, 0, 0.2, 1)';
      overlay.style.transform  = 'translate(0,0)';

      card.classList.add('hovered');
    });

    card.addEventListener('mouseleave', (e) => {
      const dir = directionFromAngle(e, card);
      lastDir = dir;

      // Slide OUT toward the exit edge
      overlay.style.transition = 'transform 0.42s cubic-bezier(0.4, 0, 0.2, 1)';
      overlay.style.transform  = getExitTransform(dir);

      card.classList.remove('hovered');
    });
  });
</script>
