<script>
document.addEventListener("DOMContentLoaded", () => {
  const section = document.getElementById("timelineSection");
  const timeline = document.querySelector(".timeline");
  const items = document.querySelectorAll(".item");

  const observer = new IntersectionObserver((entries) => {
    entries.forEach((entry) => {

      if (entry.isIntersecting) {
        // SCROLL DOWN → Animate IN
        timeline.classList.add("active");

        items.forEach((item, index) => {
          setTimeout(() => {
            item.classList.add("show");
          }, index * 300);
        });

      } else {
        // SCROLL UP → Animate OUT (reverse)
        timeline.classList.remove("active");

        items.forEach((item, index) => {
          setTimeout(() => {
            item.classList.remove("show");
          }, index * 200); // faster reverse (optional)
        });
      }

    });
  }, {
    threshold: 0.3
  });

  observer.observe(section);
});
</script>

<script>
    $(document).ready(function () {
  var owl = $('.my-carousel-consult').owlCarousel({
    loop: true,
    margin: 0,
    center: true,
    autoplay: false,
    smartSpeed: 500,
    nav: false,
    dots: false,
    responsive: {
      0:    { items: 1 },
      576:  { items: 2 },
      992:  { items: 3 },
      1200: { items: 5 }
    }
  });

  function assignActiveItemClasses() {
    $('.my-carousel-consult .owl-item').each(function () {
      var filtered = $(this).attr('class')
        .split(' ')
        .filter(function (c) {
          return !/^pos-\d+$/.test(c) &&
                 !/^prev-\d+$/.test(c) &&
                 !/^next-\d+$/.test(c) &&
                 c !== 'is-center';
        });
      $(this).attr('class', filtered.join(' '));
    });

    var $active = $('.my-carousel-consult .owl-item.active');
    var total   = $active.length;
    var mid     = Math.floor(total / 2);

    $active.each(function (i) {
      $(this).addClass('pos-' + (i + 1));
      var diff = i - mid;
      if (diff === 0) {
        $(this).addClass('is-center');
      } else if (diff < 0) {
        $(this).addClass('prev-' + Math.abs(diff));
      } else {
        $(this).addClass('next-' + diff);
      }
    });
  }

  // ✅ KEY FIX: bind BEFORE init so initialized event is caught
  owl.on('initialized.owl.carousel changed.owl.carousel', function () {
    setTimeout(assignActiveItemClasses, 0);
  });

  // ✅ SAFETY NET: also run after a short delay on page load
  setTimeout(assignActiveItemClasses, 100);

  $('#prev-btn').on('click', function () { owl.trigger('prev.owl.carousel'); });
  $('#next-btn').on('click', function () { owl.trigger('next.owl.carousel'); });
});
</script>
</body>

</html>